<?php
$config=require dirname(__DIR__)."/config.php";require dirname(__DIR__)."/lib/events.php";$events=load_events($config);$token=null;
if($_SERVER["REQUEST_METHOD"]==="POST"){
 $a=$_POST["action"]??"";
 if($a==="create"){$name=trim($_POST["name"]??"");$id=trim(strtolower(preg_replace("/[^a-zA-Z0-9]+/","-",$name)),"-");if($id){$token=new_upload_token();$events[$id]=["id"=>$id,"name"=>$name,"visibility"=>($_POST["visibility"]??"private")==="public"?"public":"private","active"=>true,"token_hash"=>token_hash($token),"created_at"=>date(DATE_ATOM),"upload_count"=>0];save_events($config,$events);}}
 if($a==="regen"&&isset($events[$_POST["id"]??""])){$id=$_POST["id"];$token=new_upload_token();$events[$id]["token_hash"]=token_hash($token);save_events($config,$events);}
 if($a==="visibility"&&isset($events[$_POST["id"]??""])){$id=$_POST["id"];$events[$id]["visibility"]=$events[$id]["visibility"]==="public"?"private":"public";save_events($config,$events);}
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Folder Manager</title><link rel="stylesheet" href="../assets/app.css"></head><body><main><h1>Event & Folder</h1><p>Kelola tujuan upload, privasi galeri dan token perangkat dari satu tempat.</p><p>Setiap folder memiliki Upload Token sendiri.</p><?php if($token):?><section><b>Copy token sekarang:</b><br><code><?=htmlspecialchars($token)?></code><p>Server hanya menyimpan hash token.</p></section><?php endif?><form method="post"><input type="hidden" name="action" value="create"><input name="name" required placeholder="Nama folder"><select name="visibility"><option value="private">Private</option><option value="public">Public</option></select><button>Buat Folder + Token</button></form><?php foreach($events as $e):?><hr><h2><?=htmlspecialchars($e["name"])?></h2><p><?=strtoupper(htmlspecialchars($e["visibility"]))?> · <?=intval($e["upload_count"]??0)?> upload</p><form method="post"><input type="hidden" name="action" value="visibility"><input type="hidden" name="id" value="<?=htmlspecialchars($e["id"])?>"><button>Ubah Public/Private</button></form><form method="post"><input type="hidden" name="action" value="regen"><input type="hidden" name="id" value="<?=htmlspecialchars($e["id"])?>"><button>Regenerate Token</button></form><?php endforeach?></main></body></html>